let ok=function Ok x->x|Error _->failwith"error"
let render winding=let s=ok(Raster2.Surface.create~pitch:28~width:6~height:6())in Raster2.Surface.clear s 0l;Raster2.Primitive.rect s~blend:Copy~x:(-2)~y:1~width:4~height:2 0xff0000ffl;Raster2.Primitive.line s~blend:Copy~x0:(-2)~y0:0~x1:5~y1:5 0x00ff00ffl;(match winding with`Forward->Raster2.Primitive.triangle s~blend:Copy(1,1)(4,1)(2,4)0x0000ffffl|`Reverse->Raster2.Primitive.triangle s~blend:Copy(4,1)(1,1)(2,4)0x0000ffffl);Raster2.Primitive.circle s~blend:Copy~cx:3~cy:3~radius:2 0xffffffffl;let bytes=Raster2.Surface.bytes s in for y=0 to 5 do if Bytes.get bytes(y*28+24)<>'\000'||Bytes.get bytes(y*28+27)<>'\000'then failwith"padding"done;bytes
let ()=let a=render`Forward and b=render`Reverse in if a<>b then failwith"winding";let s=ok(Raster2.Surface.create~width:3~height:3())in Raster2.Primitive.triangle s~blend:Copy(0,0)(1,1)(2,2)0x11223344l;if ok(Raster2.Surface.get_rgba s~x:1~y:1)<>0x11223344l then failwith"degenerate";let ws=Array.init 4(fun _->Domain.spawn(fun()->render`Forward))in Array.iter(fun w->if Domain.join w<>a then failwith"domain")ws;print_endline"Raster2 clipped primitives passed"
